async function hmacHex(payload, secret) {

  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);

  return hex(await crypto.subtle.sign("HMAC", key, enc.encode(payload)));

}

