async function ensureSettings(DB) {

  await DB.prepare("CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT)").run();

}

async function getSetting(DB, k, def) {

  await ensureSettings(DB);

  const r = await DB.prepare("SELECT v FROM settings WHERE k = ?").bind(k).first();

  return r ? r.v : def;

}

async function setSetting(DB, k, v) {

  await ensureSettings(DB);

  await DB.prepare("INSERT INTO settings (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v").bind(k, v).run();

}

async function isAdmin(request, env) {

  const pt = await parseToken((request.headers.get("authorization") || "").replace(/^Bearer\s+/i, ""), env.APP_SECRET);

  return !!(pt && pt.uid === "admin");

}

